#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    int n = s.size();
    long long count = 0;
    for (int c = 0; c < 2 * n - 1; c++) {
        int l = c / 2, rr = l + c % 2;
        while (l >= 0 && rr < n && s[l] == s[rr]) {
            count++;
            l--;
            rr++;
        }
    }
    cout << count << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int n = s.length();
        long count = 0;
        for (int c = 0; c < 2 * n - 1; c++) {
            int l = c / 2, rr = l + c % 2;
            while (l >= 0 && rr < n && s.charAt(l) == s.charAt(rr)) {
                count++;
                l--;
                rr++;
            }
        }
        System.out.println(count);
    }
}
